package pe.sga.functional;
import org.junit.jupiter.api.Test;
import pe.sga.entity.enums.RolUsuario;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SystemApiTest extends FullStackTestBase {
 @Test void SY01_saludPublica()throws Exception{var r=call("GET","/api/v1/health",null,null);assertEquals(200,r.statusCode());assertEquals("UP",tree(r).path("data").path("status").asText());}
 @Test void SY02_loginYPerfilJWT()throws Exception{var u=user(RolUsuario.ADMINISTRADOR_TI);var token=login(u);assertFalse(token.isBlank());var r=call("GET","/api/v1/auth/me",token,null);assertEquals(200,r.statusCode(),r.body());assertEquals(u.getUsername(),tree(r).path("data").path("username").asText());}
 @Test void SY03_credencialesIncorrectas()throws Exception{var u=user(RolUsuario.ADMINISTRADOR_TI);var r=call("POST","/api/v1/auth/login",null,Map.of("username",u.getUsername(),"password","INCORRECTA"));assertEquals(401,r.statusCode(),r.body());assertFalse(tree(r).path("success").asBoolean());assertFalse(r.body().contains("stackTrace"));}
 @Test void SY04_rechazoSinToken()throws Exception{var r=call("GET","/api/v1/clientes",null,null);java.nio.file.Files.createDirectories(java.nio.file.Path.of("target/qa-evidence"));java.nio.file.Files.writeString(java.nio.file.Path.of("target/qa-evidence/SY04-response.txt"),"status="+r.statusCode()+"\nheaders="+r.headers().map()+"\nbody="+r.body());assertEquals(401,r.statusCode());assertTrue(r.headers().firstValue("Content-Type").orElse("").contains("application/json"),"Se esperaba application/json; recibido "+r.headers().firstValue("Content-Type").orElse("sin tipo"));assertFalse(tree(r).path("success").asBoolean());}
 @Test void SY05_tokenInvalido()throws Exception{var r=call("GET","/api/v1/clientes","token-invalido",null);assertEquals(401,r.statusCode(),r.body());}
 @Test void SY06_rolSinPermiso()throws Exception{var u=user(RolUsuario.AGENTE_COMERCIAL);var r=call("GET","/api/v1/usuarios",login(u),null);assertEquals(403,r.statusCode(),r.body());assertFalse(tree(r).path("success").asBoolean());}
 @Test void SY07_CRUDClienteCompleto()throws Exception{var token=login(user(RolUsuario.AGENTE_COMERCIAL));String doc=unique();int id=create(token,doc);var r=call("GET","/api/v1/clientes/"+id,token,null);assertEquals(200,r.statusCode());assertEquals(doc,tree(r).path("data").path("numeroDocumento").asText());var d=dto(doc);d.setRazonSocial("QA HTTP Actualizada");assertEquals(200,call("PUT","/api/v1/clientes/"+id,token,d).statusCode());assertEquals("QA HTTP Actualizada",clientes.findById(id).orElseThrow().getRazonSocial());assertEquals(200,call("DELETE","/api/v1/clientes/"+id,token,null).statusCode());r=call("GET","/api/v1/clientes/"+id,token,null);assertFalse(tree(r).path("data").path("estadoActivo").asBoolean());assertTrue(clientes.existsById(id));}
 @Test void SY08_validacionCorreoNoInserta()throws Exception{var token=login(user(RolUsuario.AGENTE_COMERCIAL));String doc=unique();var d=dto(doc);d.setCorreoContacto("INVALIDO");var r=call("POST","/api/v1/clientes",token,d);assertEquals(400,r.statusCode(),r.body());assertFalse(clientes.existsByNumeroDocumento(doc));assertTrue(tree(r).path("data").has("correoContacto"));}
 @Test void SY09_recursoInexistente404()throws Exception{var token=login(user(RolUsuario.AGENTE_COMERCIAL));var r=call("GET","/api/v1/clientes/2147483647",token,null);assertEquals(404,r.statusCode(),r.body());assertFalse(tree(r).path("success").asBoolean());}
 @Test void SY10_duplicado400()throws Exception{var token=login(user(RolUsuario.AGENTE_COMERCIAL));String doc=unique();create(token,doc);var r=call("POST","/api/v1/clientes",token,dto(doc));assertEquals(400,r.statusCode(),r.body());assertEquals(1,clientes.findAll().stream().filter(c->doc.equals(c.getNumeroDocumento())).count());}
 @Test void SY11_catalogoPublico()throws Exception{var r=call("GET","/api/v1/catalogos/puertos",null,null);assertEquals(200,r.statusCode(),r.body());assertTrue(tree(r).path("data").isArray());assertTrue(tree(r).path("data").size()>0);}
 @Test void SY12_longitudInvalida400()throws Exception{var token=login(user(RolUsuario.AGENTE_COMERCIAL));var d=dto("1234567890123456");var r=call("POST","/api/v1/clientes",token,d);assertEquals(400,r.statusCode(),r.body());assertFalse(clientes.existsByNumeroDocumento(d.getNumeroDocumento()));}
}
